// Sources, in priority order:
//   1. GITHUB_ORG        - paginate the GitHub org repos API (all pages)
//   2. REPO_LIST_URL     - JSON array of { name, url, target?, pipelines? }
//   3. static list below - mirrors pipeline/config.py DEFAULT_REPOS
//
// Every emitted item carries a runId (one batch) so workers + aggregator can
// group results, plus the pipelines it should be scanned by.
const pipelines = ($env.PIPELINES || 'transit,internal')
  .split(',').map((s) => s.trim()).filter(Boolean);

const items = [];

if ($env.GITHUB_ORG) {
  const token = $env.GITHUB_TOKEN || '';
  const headers = token ? { Authorization: 'Bearer ' + token } : {};
  const maxPages = parseInt($env.GITHUB_MAX_PAGES, 10) || 50;
  for (let page = 1; page <= maxPages; page++) {
    const repos = await this.helpers.httpRequest({
      url: 'https://api.github.com/orgs/' + $env.GITHUB_ORG + '/repos?per_page=100&page=' + page,
      method: 'GET',
      headers,
      json: true,
    });
    if (!Array.isArray(repos) || repos.length === 0) break;
    for (const r of repos) items.push({ name: r.name, url: r.clone_url, pipelines });
    if (repos.length < 100) break;
  }
} else if ($env.REPO_LIST_URL) {
  const list = await this.helpers.httpRequest({
    url: $env.REPO_LIST_URL,
    method: 'GET',
    json: true,
  });
  for (const r of Array.isArray(list) ? list : (list.repos || [])) {
    items.push({
      name: r.name,
      url: r.url || '',
      target: r.target || '',
      pipelines: r.pipelines || pipelines,
    });
  }
} else {
  const defaults = [
    { name: 'go-gin', url: 'https://github.com/gin-gonic/gin' },
    { name: 'java-springboot', url: 'https://github.com/spring-projects/spring-boot' },
    { name: 'os-nova', url: 'https://github.com/openstack/nova' },
  ];
  for (const r of defaults) items.push({ name: r.name, url: r.url, pipelines });
}

const runId = 'run-' + new Date().toISOString().replace(/[:.]/g, '-');
const enqueuedAt = Date.now();

return items
  .filter((r) => r.name && (r.url || r.target))
  .map((r) => ({ json: { ...r, runId, enqueuedAt } }));

// Group repos by pipeline first, then chunk each pipeline separately so a
// worker execution never handles mixed pipelines. Chunks are exchanged as
// files on the shared run volume, so N worker instances pull from one queue.
const CHUNK = parseInt($env.CHUNK_SIZE, 10) || 50;
const root = $env.RUN_ROOT || ($env.MULTITOOL_ROOT || '/opt/multi-tool') + '/n8n/runs';

const items = $input.all();
const runId = items[0] && items[0].json.runId ? items[0].json.runId : ('run-' + Date.now());

const byPipeline = {};
for (const it of items) {
  const r = it.json;
  const ps = r.pipelines && r.pipelines.length ? r.pipelines : ['transit'];
  for (const p of ps) {
    (byPipeline[p] = byPipeline[p] || []).push({
      name: r.name,
      url: r.url || '',
      target: r.target || '',
    });
  }
}

const chunks = [];
for (const pipeline of Object.keys(byPipeline)) {
  const list = byPipeline[pipeline];
  for (let i = 0; i < list.length; i += CHUNK) {
    const slice = list.slice(i, i + CHUNK);
    const chunkId = pipeline + '-' + String(Math.floor(i / CHUNK)).padStart(4, '0');
    const payload = { chunkId, runId, pipeline, repos: slice };
    const jobDir = root + '/jobs/' + pipeline;
    chunks.push({
      json: {
        chunkId,
        runId,
        pipeline,
        repoCount: slice.length,
        jobDir,
        jobFile: jobDir + '/' + chunkId + '.json',
        jobBase64: Buffer.from(JSON.stringify(payload)).toString('base64'),
        manifestFile: root + '/manifests/' + runId + '.txt',
      },
    });
  }
}

return chunks;
